import{_ as t,o as n,c as a,a4 as o}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0050 — Verrou « clé attendue » : l'amorçage se ferme dès le provisionnement","description":"Extrait de docs/adr/0050-verrou-cle-attendue-au-provisionnement.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0050 — Verrou « clé attendue » : l'amorçage se ferme dès le provisionnement","description":"Extrait de docs/adr/0050-verrou-cle-attendue-au-provisionnement.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0050-verrou-cle-attendue-au-provisionnement.md","filePath":"developpeurs/adr/0050-verrou-cle-attendue-au-provisionnement.md"}`),r={name:"developpeurs/adr/0050-verrou-cle-attendue-au-provisionnement.md"};function i(s,e,l,u,d,c){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0050--verrou--clé-attendue---lamorçage-se-ferme-dès-le-provisionnement" tabindex="-1">ADR-0050 — Verrou « clé attendue » : l&#39;amorçage se ferme dès le provisionnement <a class="header-anchor" href="#adr-0050--verrou--clé-attendue---lamorçage-se-ferme-dès-le-provisionnement" aria-label="Permalink to &quot;ADR-0050 — Verrou « clé attendue » : l&#39;amorçage se ferme dès le provisionnement {#adr-0050--verrou--clé-attendue---lamorçage-se-ferme-dès-le-provisionnement}&quot;">​</a></h1><p><strong>Date :</strong> 26 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constat SEC-1 (élevé) ; amende le garde-fou (« Négatives ») de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0026-installation-guidee-cle-d-installation">ADR-0026</a> ; s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0039-journalisation-applicative">ADR-0039</a> (aucun secret dans les journaux), l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0031-limitation-de-debit">ADR-0031</a> (limitation de débit) et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0045-deploiement-par-un-exploitant-non-developpeur">ADR-0045</a> (pile de production et installateur)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0026 protège l&#39;installation guidée par une clé et ferme <code>POST /api/v1/auth/bootstrap</code> dès qu&#39;une clé est <strong>en attente</strong>. Elle assume un garde-fou : une organisation <strong>sans</strong> clé reste amorçable par le premier venu.</p><p>L&#39;ADR-0045 a ensuite séparé, en production, la création de l&#39;organisation et l&#39;émission de la clé. <code>python -m app.cli.provision</code> crée l&#39;organisation à chaque démarrage de <code>cms-api</code> sans émettre de clé, pour ne pas en écrire une dans des journaux qui peuvent partir vers un agrégateur externe (ADR-0039). L&#39;installateur l&#39;émet ensuite, par <code>python -m app.cli.installation_key</code>.</p><p>L&#39;audit du 26/09 (SEC-1) relève la fenêtre qui en résulte :</p><ul><li><strong>Entre le démarrage de l&#39;API et l&#39;émission de la clé</strong>, l&#39;organisation de production n&#39;a ni compte ni clé. L&#39;amorçage lui est ouvert, sans captcha ni limite de débit.</li><li><strong>Si l&#39;émission échoue</strong>, l&#39;installateur n&#39;affiche qu&#39;un avertissement. La fenêtre reste alors ouverte indéfiniment.</li><li><strong>L&#39;identifiant d&#39;organisation n&#39;est pas un secret</strong> : il figure dans la configuration de l&#39;admin (<code>NUXT_PUBLIC_ORGANIZATION_ID</code>).</li><li><strong>La route est joignable</strong> dès que l&#39;API est exposée : gabarit <code>api.caddy</code>, profil « Sur mesure » ou <code>--api-publique</code>.</li></ul><p>Un tiers qui connaît l&#39;adresse peut donc créer le premier administrateur à la place de l&#39;exploitant : c&#39;est le détournement d&#39;installation que l&#39;ADR-0026 voulait fermer.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><p><strong><code>provision</code> pose un verrou « clé attendue »</strong> sur une organisation non installée. Le verrou est rangé sous <code>organizations.settings[&quot;installation&quot;]</code> (<code>{&quot;awaiting_key&quot;: true, &quot;locked_at&quot;: …}</code>), dans le namespace de la clé.</p><ul><li>Il ne contient <strong>aucun secret</strong> : <code>provision</code> reste muette sur les clés, et l&#39;ADR-0039 est respectée.</li><li>Il est posé à chaque démarrage tant que l&#39;organisation n&#39;est pas installée. Il couvre donc aussi une organisation provisionnée avant cette décision.</li><li>Il <strong>ne remplace jamais</strong> une clé déjà émise (<code>lock_installation</code> ne touche pas un namespace renseigné). Redémarrer <code>cms-api</code> après l&#39;installateur n&#39;invalide pas la clé.</li></ul></li><li><p><strong>L&#39;émission de la clé remplace le verrou</strong> par l&#39;empreinte de la clé (<code>issue_installation_key</code>, inchangé). L&#39;installation la consomme puis efface le namespace, comme aujourd&#39;hui.</p></li><li><p><strong>L&#39;amorçage se ferme dès que le namespace d&#39;installation est renseigné</strong> (<code>requires_installation_key</code>), et plus seulement quand une clé est lisible. Cela couvre :</p><ul><li>une clé émise ;</li><li>un verrou ;</li><li>un contenu illisible : le doute ferme la porte, comme un enregistrement illisible n&#39;ouvre aucune installation.</li></ul><p>Le 409 renvoie vers <code>POST /api/v1/installation</code> et vers la commande d&#39;émission.</p></li><li><p><strong><code>POST /auth/bootstrap</code> reçoit la limite <code>installation_per_ip</code></strong> (10 essais par 15 minutes par défaut). C&#39;est la politique et le compteur de <code>POST /installation</code> : les deux portes du premier compte ne peuvent pas s&#39;additionner.</p></li><li><p><strong>L&#39;échec d&#39;émission de l&#39;installateur reste un avertissement.</strong> Avec le verrou, un échec ne rouvre plus rien : l&#39;organisation attend sa clé, et l&#39;avertissement donne la commande pour l&#39;émettre. Rendre cet échec bloquant arrêterait une installation dont la pile tourne déjà, sans gain de sécurité.</p></li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong><code>provision</code> émet la clé et l&#39;affiche</strong></td><td>L&#39;ADR-0045 l&#39;a écartée pour une bonne raison : les journaux du conteneur peuvent partir vers un tiers (ADR-0039), et une clé nouvelle à chaque démarrage invaliderait celle que l&#39;exploitant est en train de recopier.</td></tr><tr><td><strong>Désactiver <code>bootstrap</code> en production par un réglage</strong></td><td>Un réglage de plus à poser, et une organisation provisionnée par une intégration qui l&#39;oublie retrouve la faille. Le verrou, lui, est posé par le chemin de provisionnement lui-même.</td></tr><tr><td><strong>Rendre bloquant l&#39;échec de <code>emettre_cle</code></strong> (piste de l&#39;audit)</td><td>Inutile une fois le verrou posé (cf. n°5).</td></tr><tr><td><strong>Supprimer <code>bootstrap</code></strong></td><td>Même raison que dans l&#39;ADR-0026 : la suite de tests et les intégrations provisionnent par cette route.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>La fenêtre de SEC-1 est fermée sur le chemin de production. Du premier démarrage de <code>cms-api</code> à l&#39;installation, le premier compte ne se crée qu&#39;avec la clé.</li><li>Aucun secret n&#39;est ajouté aux journaux, aucune migration n&#39;est nécessaire, et l&#39;installateur ne change pas.</li><li>L&#39;amorçage est limité en débit, comme l&#39;installation.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Une organisation verrouillée sans clé ne peut rien faire</strong> tant que l&#39;exploitant n&#39;a pas émis la clé : <code>GET /installation/status</code> répond <code>installation_key_pending: false</code>, et l&#39;installation répond 403. C&#39;est voulu, et la commande est rappelée par le 409 de l&#39;amorçage comme par l&#39;installateur.</li><li><strong>Le garde-fou de l&#39;ADR-0026 demeure pour les organisations créées hors de <code>provision</code></strong> : une intégration qui crée une organisation sans clé ni verrou la laisse amorçable. <code>lock_installation</code> est la fonction à appeler.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Verrou posé par <code>provision</code>, amorçage fermé par <code>requires_installation_key</code>, limite <code>installation_per_ip</code> sur l&#39;amorçage — livrés avec cette ADR ; recette <code>apps/api/tests/test_installation.py</code> (verrou, remplacement par la clé, limite de débit) et <code>apps/api/tests/test_provision.py</code> (verrou posé sans effacer une clé émise).</li></ul>',19)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
